// The API client, typed from the back-end's OpenAPI specification (schema.ts, generated by
// tools/generate-api-types.sh). The session cookie travels by itself; requests that change
// state also carry the CSRF token of the session (ADR-0029).
import createClient, { type Middleware } from "openapi-fetch";
import type { components, paths } from "./schema.ts";

export type SessionView = components["schemas"]["SessionView"];
export type WorkspaceView = components["schemas"]["WorkspaceView"];
export type { components };

const SAFE_METHODS = new Set(["GET", "HEAD", "OPTIONS"]);
let csrfToken: string | null = null;

/** Remembered from the last session answer; forgotten at sign-out. */
export function setCsrfToken(token: string | null): void {
  csrfToken = token;
}

const csrf: Middleware = {
  onRequest({ request }) {
    if (!SAFE_METHODS.has(request.method) && csrfToken !== null) {
      request.headers.set("X-CSRF-Token", csrfToken);
    }
    return request;
  },
};

export const api = createClient<paths>({ baseUrl: "", credentials: "same-origin" });
api.use(csrf);

/** An answer the interface did not expect; the status helps tell what to show. */
export class ApiError extends Error {
  constructor(
    readonly status: number,
    readonly detail: string | null,
    readonly retryAfterSeconds: number | null = null,
  ) {
    super(`API error ${String(status)}${detail === null ? "" : `: ${detail}`}`);
    this.name = "ApiError";
  }
}

export function apiError(response: Response, error: unknown): ApiError {
  const detail =
    typeof error === "object" && error !== null && "detail" in error && typeof error.detail === "string"
      ? error.detail
      : null;
  const retryAfter = Number(response.headers.get("Retry-After"));
  return new ApiError(response.status, detail, Number.isFinite(retryAfter) && retryAfter > 0 ? retryAfter : null);
}
